<?php
if(!defined('ABSPATH')){exit;}
final class Orion_Conversation_Admin{
 private Orion_Conversation_Service $conversations;
 public function __construct(Orion_Conversation_Service $conversations){$this->conversations=$conversations;}
 public function render():void{if(!current_user_can('manage_woocommerce'))return;$id=absint($_GET['conversation_id']??0);echo '<section class="orion-card orion-conversations"><h2>Customer conversations</h2><p>Review every retained question and AI answer. Conversations are read-only here and follow the configured retention period.</p>';if($id){$this->render_one($id);echo '</section>';return;}$per_page=absint($_GET['conversation_per_page']??20);if(!in_array($per_page,array(20,50,100),true))$per_page=20;$total=$this->conversations->total();$pages=max(1,(int)ceil($total/$per_page));$page=min(max(1,absint($_GET['conversation_page']??1)),$pages);$items=$this->conversations->all($per_page,($page-1)*$per_page);$this->toolbar($page,$per_page,$total);if(!$items){echo '<p>No retained conversations yet.</p></section>';return;}echo '<table class="widefat striped"><thead><tr><th>Conversation</th><th>First question</th><th>Messages</th><th>AI gaps</th><th>Last activity</th></tr></thead><tbody>';foreach($items as$item){$url=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'conversations','conversation_id'=>(int)$item['id'],'return_conversation_page'=>$page,'return_conversation_per_page'=>$per_page),admin_url('admin.php'));echo '<tr><td><a href="'.esc_url($url).'">#'.(int)$item['id'].'</a></td><td>'.esc_html(mb_substr((string)($item['first_question']??''),0,180)).'</td><td>'.(int)$item['message_count'].'</td><td>'.(int)$item['gap_count'].'</td><td>'.esc_html((string)$item['last_activity']).'</td></tr>';}echo '</tbody></table>';$this->toolbar($page,$per_page,$total);echo '</section><style>.orion-conversation-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:16px 0}.orion-conversation-toolbar form{display:flex;align-items:center;gap:8px}.orion-conversation-toolbar .page-numbers{display:flex;gap:4px;align-items:center;margin:0}.orion-conversation-toolbar .page-numbers li{margin:0}.orion-conversation-toolbar .page-numbers a,.orion-conversation-toolbar .page-numbers span{display:inline-block;min-width:30px;padding:5px 8px;text-align:center;border:1px solid #c3c4c7;border-radius:4px;text-decoration:none;background:#fff}.orion-conversation-toolbar .page-numbers .current{background:#2271b1;border-color:#2271b1;color:#fff}</style>';}
 private function toolbar(int $page,int $per_page,int $total):void{if($total<1)return;$first=(($page-1)*$per_page)+1;$last=min($total,$page*$per_page);$pages=max(1,(int)ceil($total/$per_page));$base=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'conversations','conversation_per_page'=>$per_page,'conversation_page'=>'%#%'),admin_url('admin.php'));$base=str_replace('%25%23%25','%#%',$base);$links=$pages>1?paginate_links(array('base'=>$base,'format'=>'','current'=>$page,'total'=>$pages,'mid_size'=>2,'end_size'=>1,'prev_text'=>'‹','next_text'=>'›','type'=>'list')):'';echo '<nav class="orion-conversation-toolbar" aria-label="Conversation pages"><span>Showing '.(int)$first.'–'.(int)$last.' of '.(int)$total.'</span><form method="get" action="'.esc_url(admin_url('admin.php')).'"><input type="hidden" name="page" value="orion-ai-assistant"><input type="hidden" name="tab" value="conversations"><label for="orion-conversation-per-page">Per page</label><select id="orion-conversation-per-page" name="conversation_per_page">';foreach(array(20,50,100)as$value)echo '<option value="'.$value.'" '.selected($per_page,$value,false).'>'.$value.'</option>';echo '</select><button class="button">Apply</button></form>'.($links?$links:'').'</nav>';}
 private function render_one(int $id):void{$conversation=$this->conversations->get($id);if(!$conversation){echo '<p>Conversation not found.</p>';return;}$page=max(1,absint($_GET['return_conversation_page']??1));$per_page=absint($_GET['return_conversation_per_page']??20);if(!in_array($per_page,array(20,50,100),true))$per_page=20;$back=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'conversations','conversation_page'=>$page,'conversation_per_page'=>$per_page),admin_url('admin.php'));echo '<p><a href="'.esc_url($back).'">← Back to conversations</a></p><h3>Conversation #'.$id.'</h3><p class="description">Created '.esc_html((string)$conversation['created_at']).' · Last activity '.esc_html((string)$conversation['last_activity']).'</p>';$gaps=$this->conversations->gaps($id);if($gaps){echo '<div class="notice notice-warning inline"><p><strong>AI improvement gaps:</strong> ';foreach($gaps as$index=>$gap){if($index)echo ', ';$url=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'gaps','gap_id'=>(int)$gap['id']),admin_url('admin.php'));echo '<a href="'.esc_url($url).'">#'.(int)$gap['id'].' '.esc_html(str_replace('_',' ',(string)$gap['reason_code'])).'</a>';}echo '</p></div>';}$messages=$this->conversations->messages($id,300);if(!$messages){echo '<p>No stored messages.</p>';return;}echo '<div class="orion-dialogue">';foreach($messages as$message){$role=(string)$message['role'];$label=$role==='user'?'Customer':'AI assistant';echo '<article style="margin:12px 0;padding:14px;border:1px solid #dcdcde;border-left:4px solid '.($role==='user'?'#2271b1':'#00a32a').';border-radius:6px;background:#fff"><div style="display:flex;justify-content:space-between;gap:12px"><strong>'.esc_html($label).'</strong><small>'.esc_html((string)$message['created_at']).'</small></div><div style="margin-top:8px;white-space:normal">'.nl2br(esc_html((string)$message['content'])).'</div></article>';}echo '</div>';}
}
